export const LOGO_LINIEN = [{"x": 20.5, "y": 430.6, "w": 1141, "h": 9.2}, {"x": 20.5, "y": 585.9, "w": 1141, "h": 9.2}] as const;

/** Komplettes Logo als SVG-Text (für PDFs, Briefpapier und Bilder) */
export function logoSvg(grau = LOGO_GRAU, bronze = LOGO_BRONZE, nurZeichen = false): string {
  const linien = nurZeichen ? '' : LOGO_LINIEN.map((l) => `<rect x="${l.x}" y="${l.y}" width="${l.w}" height="${l.h}" rx="${l.h / 2}" fill="${bronze}"/>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${nurZeichen ? ZEICHEN_BOX : LOGO_BOX}"><path fill="${grau}" fill-rule="evenodd" d="${LOGO_KM}${nurZeichen ? '' : LOGO_TEXT}"/><path fill="${bronze}" fill-rule="evenodd" d="${LOGO_S}"/>${linien}</svg>`;
}

const cache = new Map<string, Promise<string>>();
/** Logo als PNG (data-URL) in der gewünschten Breite, z. B. für jsPDF */
export function logoPng(breite = 1200, nurZeichen = false): Promise<string> {
  const k = `${breite}-${nurZeichen}`;
  if (!cache.has(k)) cache.set(k, new Promise((ok, fehler) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement('canvas'); c.width = breite; c.height = Math.round(breite * img.height / img.width);
      c.getContext('2d')!.drawImage(img, 0, 0, c.width, c.height); ok(c.toDataURL('image/png'));
    };
    img.onerror = () => fehler(new Error('Logo konnte nicht gezeichnet werden.'));
    const svg = logoSvg(LOGO_GRAU, LOGO_BRONZE, nurZeichen);
    const [, , w, h] = (nurZeichen ? ZEICHEN_BOX : LOGO_BOX).split(' ').map(Number);
    img.width = w; img.height = h;
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg.replace('<svg ', `<svg width="${w}" height="${h}" `));
  }));
  return cache.get(k)!;
}
